type Channel = 'email' | 'sms';
type JobStatus = 'queued' | 'retry_wait' | 'sending' | 'delivered' | 'failed';
type SendResult = { ok: true } | { ok: false; retryable: boolean };

interface DeliveryJob {
  id: string;
  channel: Channel;
  attempts: number;
  recipient: string;
  payload: string;
}
interface JobRepository {
  // Atomically claims a due queued or retry_wait job and moves it to sending.
  claimDue(jobId: string): Promise<boolean>;
  schedule(jobId: string, update: { status: 'retry_wait' | 'queued'; channel: Channel; attempts: number; runAt: number }): Promise<void>;
  complete(jobId: string, status: 'delivered' | 'failed'): Promise<void>;
}
interface Provider {
  send(recipient: string, payload: string): Promise<SendResult>;
}

class QueueWorker {
  constructor(private jobs: JobRepository, private providers: Record<Channel, Provider>) {}

  async process(job: DeliveryJob): Promise<void> {
    if (!(await this.jobs.claimDue(job.id))) return;
    const result = await this.providers[job.channel].send(job.recipient, job.payload);
    if (result.ok) {
      await this.jobs.complete(job.id, 'delivered');
      return;
    }

    if (result.retryable && job.attempts < 2) {
      await this.jobs.schedule(job.id, {
        status: 'retry_wait',
        channel: job.channel,
        attempts: job.attempts + 1,
        runAt: Date.now() + 1000 * 2 ** job.attempts
      });
      return;
    }

    if (job.channel === 'email') {
      await this.jobs.schedule(job.id, {
        status: 'queued',
        channel: 'sms',
        attempts: 0,
        runAt: Date.now()
      });
      return;
    }
    await this.jobs.complete(job.id, 'failed');
  }
}
